    }
public:
    int countValidPrefixes(std::string s) {
        int vCount = 0, cCount = 0, ans = 0;
        for (char ch : s) {
            if (isVowel(ch)) vCount++;
            else if (std::isalpha(ch)) cCount++;
            if (vCount > cCount) ans++;
        }
