class Solution {
    private boolean isVowel(char c) {
        c = Character.toLowerCase(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    public int countValidPrefixes(String s) {
        int vCount = 0, cCount = 0, ans = 0;
        for (char ch : s.toCharArray()) {
            if (isVowel(ch)) vCount++;
            else if (Character.isLetter(ch)) cCount++;
            if (vCount > cCount) ans++;
        }
        return ans;
    }
}

function isVowel(c) {
    const ch = c.toLowerCase();
    return ch === 'a' || ch === 'e' || ch === 'i' || ch === 'o' || ch === 'u';
}

function countValidPrefixes(s) {
    let vCount = 0, cCount = 0, ans = 0;
    for (const ch of s) {
        if (isVowel(ch)) vCount++;
        else if (ch.toLowerCase() !== ch.toUpperCase()) cCount++;
        if (vCount > cCount) ans++;
    }
    return ans;
}
